/* prog27_soundex – reconstructed from the obfuscated binary.
 *
 * Behaviour:
 *   * If the program is invoked without an argument, or the argument is an
 *     empty string, it prints the literal string "EMPTY".
 *   * Otherwise it prints the Soundex code of the first argument.
 *
 * The Soundex algorithm implemented matches the classic US Census version:
 *   – The first letter of the input (converted to upper‑case) is kept.
 *   – Subsequent letters are mapped to digits:
 *        B, F, P, V               → 1
 *        C, G, J, K, Q, S, X, Z   → 2
 *        D, T                     → 3
 *        L                        → 4
 *        M, N                     → 5
 *        R                        → 6
 *        all other characters    → 0 (vowels, H, W, etc.)
 *   – Digits equal to the previous non‑zero digit are suppressed.
 *   – Vowels (A,E,I,O,U,Y) reset the “previous digit” to 0 so that a later
 *     identical digit can be emitted.
 *   – The letters H and W are simply ignored (they do not reset the previous
 *     digit and do not produce output).
 *   – The resulting code consists of the first letter followed by three
 *     digits; missing digits are padded with '0'.
 *
 * The program writes the result with a single call to `puts`.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for an upper‑case alphabetic character.
 * Non‑alphabetic characters (including vowels) return 0.
 */
static int soundex_digit(char c)
{
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T':                     return 3;
        case 'L':                               return 4;
        case 'M': case 'N':                     return 5;
        case 'R':                               return 6;
        default:                                return 0;
    }
}

/* Compute the Soundex code for a null‑terminated string.
 * The result buffer must have room for at least 5 characters
 * (4 characters + terminating NUL).
 */
static void compute_soundex(const char *src, char *dst)
{
    /* First character – keep it (upper‑cased). */
    dst[0] = (char)toupper((unsigned char)src[0]);

    int prev_digit = soundex_digit(dst[0]);   /* digit of the first letter */
    int out_idx    = 1;                       /* next position to fill */

    for (size_t i = 1; src[i] != '\0' && out_idx < 4; ++i) {
        char ch = (char)toupper((unsigned char)src[i]);

        /* H and W are ignored completely. */
        if (ch == 'H' || ch == 'W')
            continue;

        int digit = soundex_digit(ch);

        if (digit == 0) {
            /* Vowel (or any other non‑coded character) resets the previous digit. */
            prev_digit = 0;
            continue;
        }

        if (digit != prev_digit) {
            dst[out_idx++] = (char)('0' + digit);
            prev_digit = digit;
        }
        /* If digit == prev_digit we simply skip it. */
    }

    /* Pad with '0' if we have fewer than three digits. */
    while (out_idx < 4)
        dst[out_idx++] = '0';

    dst[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char code[5];               /* 4 characters + NUL */
    compute_soundex(argv[1], code);
    puts(code);
    return 0;
}
